//! `field_cinema` — a source-driven cinematic slice (v0.6 R6.1, issue #191).
//!
//! A synthetic, source-identified model emits a scalar field that evolves over a
//! logical tick; a probe selects a world point; and a compact compositional
//! grammar turns *what the instrument observed* into a shot, which is rendered
//! through the real `FieldView` pipeline. The film is generated by the instrument,
//! not a depiction of one — see `cinema.rs` for the thesis and the causal chain.
//!
//! ```sh
//! cargo run --example field_cinema                 # 8 ticks, probe tracks the peak
//! cargo run --example field_cinema -- --ticks=12
//! cargo run --example field_cinema -- --probe=10,8 # a fixed world-point selection
//! cargo run --example field_cinema -- --selfcheck  # assert the causal invariants
//! cargo run --example field_cinema -- --live        # the live-wire film (real producer)
//! cargo run --example field_cinema -- --live --suppress   # the honest non-transform
//! cargo run --example field_cinema -- --live --replay     # prove the film is deterministic
//! ```
//!
//! `--selfcheck` exits non-zero if any causal invariant is violated; it is the
//! live counterpart to `tests/field_cinema_mutation.rs`. `--live` drives the real
//! Python↔Rust producer (`bindings/python/producer.py`) through the six-beat causal
//! arc and renders each beat — the live counterpart to
//! `tests/field_cinema_causal_oracle.rs`.

mod cinema;
mod envelope;
mod film;
mod live;
mod live_link;
// The certified presentation-side transport, command channel, and source classifier from the
// scientific instrument — reused, not reimplemented (RXIV Gate B).
#[path = "../wire_instrument/capture.rs"]
mod capture;
#[path = "../wire_instrument/channel.rs"]
mod channel;
#[path = "../wire_instrument/input.rs"]
mod input;
#[path = "../wire_instrument/trace.rs"]
mod trace;
#[path = "../wire_instrument/transport.rs"]
mod transport;

