/// The terminal rectangle every shot is framed into.
const ANCHOR: Rect = Rect {
    x: 0,
    y: 0,
    width: 56,
    height: 18,
};

fn main() -> ExitCode {
    let args: Vec<String> = std::env::args().skip(1).collect();
    if args.iter().any(|a| a == "--help" || a == "-h") {
        print_help();
        return ExitCode::SUCCESS;
    }
    if args.iter().any(|a| a == "--selfcheck") {
        return selfcheck();
    }
    if args.iter().any(|a| a == "--envelope") {
        // RXIV Gate G2: a bounded, measured resource/latency envelope (see envelope.rs).
        let frames = arg_value(&args, "--frames")
            .and_then(|v| v.parse().ok())
            .unwrap_or(1000);
        let secs = arg_value(&args, "--stream-secs")
            .and_then(|v| v.parse().ok())
            .unwrap_or(10.0);
        return match envelope::run(frames, secs) {
            Ok(report) => {
                println!("{report}");
                ExitCode::SUCCESS
            }
            Err(e) => {
                eprintln!("field_cinema --envelope FAILED — {e}");
                ExitCode::FAILURE
            }
        };
    }
    if let Some(dir) = arg_value(&args, "--replay-film") {
        return replay_film_cmd(dir);
    }
    if args.iter().any(|a| a == "--live") {
        if args.iter().any(|a| a == "--interactive") {
            return run_interactive_film(&args);
        }
        return run_live(&args);
    }

    let mut ticks: u64 = 8;
    let mut probe: Option<Point> = None;
    for a in &args {
        if let Some(n) = a.strip_prefix("--ticks=") {
            ticks = n.parse().unwrap_or(8);
        } else if let Some(xy) = a.strip_prefix("--probe=") {
            probe = parse_point(xy);
        }
    }

    let model = Model::new(SourceId(42), 1);
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let _ = writeln!(
        out,
        "field_cinema — source {} epoch {} — {}x{} field, {}x{} frame\n\
         the shot is a pure function of what the instrument observed (no clock, no RNG)\n",
        model.source().0,
        model.epoch(),
        cinema::COLS,
        cinema::ROWS,
        ANCHOR.width,
        ANCHOR.height,
    );

    for tick in 0..ticks {
        // Default selection tracks the hotspot so the probe-driven punch-in is
        // visible; an explicit --probe pins a fixed world point instead.
        let sel = probe.unwrap_or_else(|| model.hotspot_center(tick));
        let staged = cinema::stage_tick(&model, tick, sel, ANCHOR);
        print_receipt(&mut out, &staged, sel);
        print_preview(&mut out, &model, tick, &staged.shot);
        let _ = writeln!(out);
    }
    ExitCode::SUCCESS
}

fn print_receipt<W: Write>(out: &mut W, staged: &cinema::Staged, sel: Point) {
    let o = &staged.observation;
    let s = &staged.shot;
    let r = &staged.frame.report;
    let peak = o
        .peak_center
        .map(|p| format!("({:.1},{:.1})", p.x, p.y))
        .unwrap_or_else(|| "none".into());
    let reading = s
        .probe_reading
        .map(|v| format!("{v:.3}"))
        .unwrap_or_else(|| "·".into());
    let _ = writeln!(
        out,
        "tick {:>2} | peak {peak} v={:.3} span={:.3} masked={:.1}% \
         | sel ({:.1},{:.1})→{reading} | shot focus=({:.1},{:.1}) zoom={:.2} {} {:?} \
         | render value={} masked={} off={} clip={} conserves={}",
        o.tick,
        o.peak_value.unwrap_or(f64::NAN),
        o.range_span,
        o.masked_fraction * 100.0,
        sel.x,
        sel.y,
        s.focus.x,
        s.focus.y,
        s.zoom,
        colormap_tag(s.colormap),
        s.emphasis,
        r.value_cells,
        r.masked_cells,
        r.off_field_cells,
        r.clipped_cells,
        r.conserves(),
    );
}

/// A colour-free preview of the shot's framing, rendered with the density ramp so
/// intensity is legible in any terminal. This is a mono *preview* of the staged
/// shot's framing, not a second render path — the real shot keeps its own
/// colormap (reported above as `cmap`).
fn print_preview<W: Write>(out: &mut W, model: &Model, tick: u64, shot: &Shot) {
    let (data, mask) = model.frame_buffers(tick);
    let view = FieldView::new(model.extent(), &data, Some(&mask)).expect("model geometry");
    let wv = view_focused_on(shot.focus, shot.zoom, ANCHOR);
    let frame = view.render(&wv, ANCHOR, Colormap::Density, RangePolicy::Auto);
    dump_surface(out, &frame.surface);
}

fn dump_surface<W: Write>(out: &mut W, surface: &Surface) {
    let mut line = String::with_capacity(surface.width as usize + 2);
    for y in 0..surface.height {
        line.clear();
        line.push_str("  ");
        for x in 0..surface.width {
            let ch = surface
                .get(x, y)
                .map(|c| c.glyph.grapheme.as_str())
                .filter(|s| !s.is_empty())
                .unwrap_or(" ");
            line.push_str(ch);
        }
        let _ = writeln!(out, "{line}");
    }
}

fn colormap_tag(c: Colormap) -> &'static str {
    match c {
        Colormap::Heat => "heat",
        Colormap::Grayscale => "gray",
        Colormap::Density => "density",
    }
}

fn parse_point(s: &str) -> Option<Point> {
    let (a, b) = s.split_once(',')?;
    Some(Point::new(a.trim().parse().ok()?, b.trim().parse().ok()?))
}

fn print_help() {
    println!(
        "field_cinema — source-driven cinematic slice (#191)\n\n\
         --ticks=N        number of logical ticks to stage (default 8)\n\
         --probe=X,Y      pin the selection to a world point (default: tracks the peak)\n\
         --selfcheck      assert the causal invariants and exit non-zero on violation\n\
         --live           the live-wire film: drive the REAL producer through the six-beat arc\n\
         --suppress       (with --live) --freeze-amplitude the producer: the honest non-transform\n\
         --reduced-motion (with --live) show only the key beats' frames, not every drift\n\
         --replay         (with --live) run the film twice and prove it is byte-identical\n\
         --interactive    (with --live) the interactive instrument-film: arrows probe, [ ] target,\n\
                          Enter intervene, space step, a auto, r resolve, q quit\n\
         --step           (with --interactive) start paused (space advances one frame)\n\
         --shape ring     (with --interactive) the non-Gaussian holdout source\n\
         --mask-every N   (with --interactive) a deterministic sparse mask on the source\n\
         --record DIR     (with --interactive) commit the film's capture + causal trace to DIR\n\
         --replay-film DIR  re-derive a recorded film's decisions with no producer\n\
         --help           this message\n\n\
         --live spawns bindings/python/producer.py; set GIBSON_PYTHON to pick the interpreter."
    );
}

// ---------------------------------------------------------------------------
// --live — the live-wire film: the REAL producer driven through the six-beat
// causal arc. Lockstep and sleep-free; the live counterpart to
// tests/field_cinema_causal_oracle.rs. The transform is earned by an OBSERVED
// authoritative change, never by the producer's ack alone — so --suppress
// (an acknowledged-but-frozen edit) honestly never transforms.
// ---------------------------------------------------------------------------

/// The presenter's intended set-amplitude target (its own command stamp; the arc's transform
/// threshold is a fraction of this). The producer's authoritative value is observed, not trusted.
const LIVE_TARGET: f64 = 2.0;

fn run_live(args: &[String]) -> ExitCode {
    let suppress = args.iter().any(|a| a == "--suppress");
    let reduced = args.iter().any(|a| a == "--reduced-motion");

    if args.iter().any(|a| a == "--replay") {
        // Determinism proof: the same lockstep script yields the identical beat path and
        // byte-identical final frame. No film is printed on the first pass.
        let (a, b) = match (film_frames(suppress), film_frames(suppress)) {
            (Ok(a), Ok(b)) => (a, b),
            (Err(e), _) | (_, Err(e)) => {
                eprintln!("field_cinema --live --replay FAILED — {e}");
                return ExitCode::FAILURE;
            }
        };
        let identical = a == b;
        println!(
            "field_cinema --live --replay{}\n  pass A: {} beats, final frame {}x{}\n  pass B: {} beats, final frame {}x{}\n  {} the live-wire film is deterministic (byte-identical replay)",
            if suppress { " --suppress" } else { "" },
            a.0.len(),
            a.1.width,
            a.1.height,
            b.0.len(),
            b.1.width,
            b.1.height,
            if identical { "OK —" } else { "FAILED —" },
        );
        return if identical {
            ExitCode::SUCCESS
        } else {
            ExitCode::FAILURE
        };
    }

    let color = io::stdout().is_terminal();
    let stdout = io::stdout();
    let mut out = stdout.lock();
    let spec = ProducerSpec::reference(suppress);
    let mut session = match LiveSession::spawn(&spec, LIVE_SOURCE) {
        Ok(s) => s,
        Err(e) => {
            let _ = writeln!(out, "field_cinema --live FAILED — {e}");
            return ExitCode::FAILURE;
        }
    };
    let _ = writeln!(
        out,
        "field_cinema --live{} — source {LIVE_SOURCE}, producer pid {}, the film is CAUSED BY a real cross-process field\n\
         six beats: ESTABLISH → DISCOVER → INTERVENE → AWAIT → TRANSFORM → RESOLVE\n\
         the transform is earned by an OBSERVED authoritative change — never the ack alone ({} output)\n",
        if suppress { " --suppress" } else { "" },
        session.producer_pid().unwrap_or(0),
        if color { "terminal" } else { "piped/mono" },
    );
    // On ANY error the session is dropped here (stdin EOF → kill backstop → OS wait → reader
    // join), so the producer is reaped on the failure path too, and the typed error is reported.
    match scripted_film(&mut out, &mut session, reduced) {
        Ok(()) => {
            let end = session.finish(SHUTDOWN_GRACE);
            let _ = writeln!(
                out,
                "  producer exit {} ({})",
                end.exit.map_or("unknown".to_string(), |s| s.to_string()),
                if end.graceful {
                    "graceful"
                } else {
                    "killed after grace"
                },
            );
            ExitCode::SUCCESS
        }
        Err(e) => {
            let _ = writeln!(out, "field_cinema --live FAILED — {e}");
            drop(session);
            ExitCode::FAILURE
        }
    }
}

/// The scripted lockstep film: every producer interaction goes through the typed session.
fn scripted_film<W: Write>(
    out: &mut W,
    session: &mut LiveSession,
    reduced: bool,
) -> Result<(), LiveError> {
    let mut arc = Arc::new();

    // ESTABLISH — the unsolicited seq=1 authoritative field sets the baseline.
    let f0 = session.next_field()?;
    let (o0, shot0, _surf0) = staged(&f0)?;
    arc.observe(arc_summary(&o0, f0.cursor));
    let baseline = o0.peak_value.unwrap_or(f64::NAN);
    beat_line(out, arc.beat(), &format!("baseline peak {baseline:.3}"));
    if !reduced {
        if let Some(p) = mono_preview(&f0.field, &shot0) {
            dump_surface(out, &p);
        }
        let _ = writeln!(out);
    }

    // DISCOVER — probe the field and watch it evolve one tick: the natural-variation calibration
    // the effect contract requires before any change can be attributed.
    arc.discover();
    let fc = session.step()?;
    let (oc, _shotc, _surfc) = staged(&fc)?;
    arc.observe(arc_summary(&oc, fc.cursor));
    let (n, drift) = arc.calibration();
    beat_line(
        out,
        arc.beat(),
        &format!("probing the field center; natural variation {drift:.4} over {n} observations"),
    );
    // INTERVENE — arm the expected effect against the calibrated baseline.
    let armed = arc.intervene(LIVE_TARGET);
    beat_line(
        out,
        arc.beat(),
        &format!(
            "issuing set-amplitude {LIVE_TARGET:.1} (expected effect: {})",
            if armed.is_unevidenceable() {
                armed.label()
            } else {
                "evidenceable"
            }
        ),
    );

    // The producer's TRUE verdict, correlated to THIS command id through the ledger.
    let id = session.submit_amplitude(LIVE_TARGET)?;
    let ack = session.await_verdict(id)?;
    arc.verdict(verdict_of(ack));
    beat_line(
        out,
        arc.beat(),
        &format!("producer verdict for command {id}: {ack:?}"),
    );

    // Advance one tick and OBSERVE the authoritative field. This — not the ack — is the only
    // path into TRANSFORM.
    let f1 = session.step()?;
    let (o1, shot1, _surf1) = staged(&f1)?;
    let ev = arc.observe(arc_summary(&o1, f1.cursor));
    let after = o1.peak_value.unwrap_or(f64::NAN);
    let label = ev.map_or("unclassified", |e| e.label());
    match arc.beat() {
        Beat::Transform => beat_line(
            out,
            arc.beat(),
            &format!("observed peak {after:.3}: {label} — the change is evidenced (not a proof of mechanism)"),
        ),
        _ => beat_line(
            out,
            arc.beat(),
            &format!(
                "acknowledged, observed peak {after:.3}: {label} — no consistent change, no transformation (honest)"
            ),
        ),
    }
    if let Some(p) = mono_preview(&f1.field, &shot1) {
        dump_surface(out, &p);
    }
    let _ = writeln!(
        out,
        "  shot focus=({:.1},{:.1}) zoom={:.2} {} {:?}",
        shot1.focus.x,
        shot1.focus.y,
        shot1.zoom,
        colormap_tag(shot1.colormap),
        shot1.emphasis,
    );

    // RESOLVE — the transform latch (if earned) survives the close.
    arc.resolve();
    beat_line(
        out,
        arc.beat(),
        if arc.transformed() {
            "the film resolves on a transformed field"
        } else {
            "the film resolves unchanged — the edit was acknowledged but never took hold"
        },
    );
    Ok(())
}

/// Stage an admitted frame, mapping an unpresentable geometry to a typed error.
fn staged(
    f: &live_link::LiveField,
) -> Result<(cinema::FieldObservation, Shot, Surface), LiveError> {
    stage_live(f).ok_or(LiveError::Disconnected {
        read_error: None,
        truncated_bytes: 0,
        exit: None,
        stderr: "an admitted frame's geometry was not presentable".into(),
    })
}

/// Print one beat line: `[BEAT] note`.
fn beat_line<W: Write>(out: &mut W, beat: Beat, note: &str) {
    let tag = match beat {
        Beat::Establish => "ESTABLISH",
        Beat::Discover => "DISCOVER",
        Beat::Intervene => "INTERVENE",
        Beat::Await => "AWAIT",
        Beat::Transform => "TRANSFORM",
        Beat::Resolve => "RESOLVE",
    };
    let _ = writeln!(out, "[{tag:>9}] {note}");
}

/// Run the whole lockstep film headlessly and return its beat path and final surface — the unit
/// the `--replay` determinism proof compares.
fn film_frames(suppress: bool) -> Result<(Vec<Beat>, Surface), LiveError> {
    let mut session = LiveSession::spawn(&ProducerSpec::reference(suppress), LIVE_SOURCE)?;
    let mut arc = Arc::new();
    let mut beats = Vec::new();

    let f0 = session.next_field()?;
    let (o0, _s0, _surf0) = staged(&f0)?;
    arc.observe(arc_summary(&o0, f0.cursor));
    beats.push(arc.beat());
    arc.discover();
    let fc = session.step()?;
    let (oc, _sc, _surfc) = staged(&fc)?;
    arc.observe(arc_summary(&oc, fc.cursor));
    beats.push(arc.beat());
    arc.intervene(LIVE_TARGET);
    beats.push(arc.beat());
    let id = session.submit_amplitude(LIVE_TARGET)?;
    let ack = session.await_verdict(id)?;
    arc.verdict(verdict_of(ack));
    beats.push(arc.beat());
    let f1 = session.step()?;
    let (o1, _s1, surf1) = staged(&f1)?;
    arc.observe(arc_summary(&o1, f1.cursor));
    beats.push(arc.beat());
    arc.resolve();
    beats.push(arc.beat());
    session.finish(SHUTDOWN_GRACE);
    Ok((beats, surf1))
}

// ---------------------------------------------------------------------------
// --live --interactive — the interactive instrument-film (RXIV Gate C) with causal
// record/replay (Gate D4). The scripted --live above stays the deterministic CI film.
// ---------------------------------------------------------------------------

fn arg_value<'a>(args: &'a [String], flag: &str) -> Option<&'a str> {
    args.iter()
        .position(|a| a == flag)
        .and_then(|i| args.get(i + 1))
        .map(|s| s.as_str())
}

fn run_interactive_film(args: &[String]) -> ExitCode {
    use film::{Film, FilmConfig};
    let has = |f: &str| args.iter().any(|a| a == f);
    let mut extra: Vec<&str> = Vec::new();
    if let Some(shape) = arg_value(args, "--shape") {
        extra.extend(["--shape", shape]);
    }
    if let Some(m) = arg_value(args, "--mask-every") {
        extra.extend(["--mask-every", m]);
    }
    let spec = ProducerSpec::reference_with(has("--suppress"), &extra);
    let mut session = match LiveSession::spawn(&spec, LIVE_SOURCE) {
        Ok(s) => s,
        Err(e) => {
            eprintln!("field_cinema --live --interactive FAILED — {e}");
            return ExitCode::FAILURE;
        }
    };
    let pid = session.producer_pid().unwrap_or(0);
    // If terminal init fails the session drops here and reaps the producer.
    let mut ctx = match gibson::context::Context::fullscreen() {
        Ok(c) => c,
        Err(e) => {
            eprintln!("field_cinema --live --interactive: terminal init failed — {e}");
            return ExitCode::FAILURE;
        }
    };
    let mut film = Film::new(FilmConfig {
        reduced_motion: has("--reduced-motion"),
        auto_advance: !has("--step"),
    });
    film.set_producer_pid(session.producer_pid());
    let loop_result = film_loop(&mut ctx, &mut session, &mut film);
    let restore_result = ctx.restore();
    let end = session.finish(SHUTDOWN_GRACE);

    let mut ok = loop_result.is_ok() && restore_result.is_ok() && film.failure().is_none();
    if let Some(dir) = arg_value(args, "--record") {
        match record_film(std::path::Path::new(dir), film.record()) {
            Ok((cap, causal)) => println!(
                "film-record: {dir} ({} frames{}, {} events; capture-digest {cap:016x} causal-digest {causal:016x})",
                film.record().frames.len(),
                if film.record().frames_truncated { ", truncated" } else { "" },
                film.record().trace.len(),
            ),
            Err(e) => {
                eprintln!("film-record FAILED: {e}");
                ok = false;
            }
        }
    }
    println!("film-path: {}", film::beat_path(film.beats()));
    println!(
        "film-beats-digest: {:016x}",
        film::beats_digest(film.beats())
    );
    println!(
        "film-summary: transforms {} · outcome {:?} · producer pid {pid} exit {} ({})",
        film.arc().transforms(),
        film.arc().last_outcome(),
        end.exit.map_or("unknown".to_string(), |s| s.to_string()),
        if end.graceful {
            "graceful"
        } else {
            "killed after grace"
        },
    );
    if let Some(f) = film.failure() {
        println!("film-failure: {f}");
    }
    if let Err(e) = loop_result {
        eprintln!("field_cinema --live --interactive: {e}");
    }
    if ok {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    }
}

/// The interactive loop: inbound frames (in stream order) then the correlated verdict, then input,
/// then at most one auto-advance in flight, then paint.
fn film_loop(
    ctx: &mut gibson::context::Context,
    session: &mut LiveSession,
    film: &mut film::Film,
) -> io::Result<()> {
    use film::FilmAction;
    use gibson::capability::ColorDepth;
    use gibson::input::Event;
    use std::time::{Duration, Instant};
    let start = Instant::now();
    let mut awaiting_field = true; // seq 1 arrives unsolicited
    let mut last_advance = Instant::now();
    loop {
        let ev = ctx.run_once(Duration::from_millis(16))?;
        let now = start.elapsed();
        // Frames before the verdict: a frame that predates the ACK reaches the arc while it is
        // still in INTERVENE, where it neither calibrates nor evidences.
        loop {
            match session.poll_field() {
                Ok(Some(f)) => {
                    film.on_field(f, now);
                    awaiting_field = false;
                }
                Ok(None) => break,
                Err(e) => {
                    film.on_failure(&e, now);
                    break;
                }
            }
        }
        if let Some(id) = film.pending() {
            match session.poll_verdict(id) {
                Ok(Some(st)) => film.on_verdict(id, st, now),
                Ok(None) => {
                    film.check_verdict_deadline(now);
                }
                Err(e) => film.on_failure(&e, now),
            }
        }
        if let Some(Event::Key(k)) = &ev {
            match film.on_key(k.code, now) {
                FilmAction::Quit => {
                    film.finish(now);
                    break;
                }
                FilmAction::Submit(v) => match session.submit_amplitude(v) {
                    Ok(id) => film.on_submitted(id, trace::Admission::Accepted, now),
                    Err(LiveError::Transport {
                        command_id: Some(id),
                        uncertain: true,
                        ..
                    }) => film.on_submitted(id, trace::Admission::TransportUncertain, now),
                    Err(e) => film.on_submit_failed(&e, now),
                },
                FilmAction::Step => {
                    if !awaiting_field && film.failure().is_none() {
                        match session.advance() {
                            Ok(()) => {
                                awaiting_field = true;
                                last_advance = Instant::now();
                            }
                            Err(e) => film.on_failure(&e, now),
                        }
                    }
                }
                FilmAction::Nothing => {}
            }
        }
        if film.auto()
            && !awaiting_field
            && film.pending().is_none()
            && last_advance.elapsed() >= film::AUTO_PERIOD
        {
            match session.advance() {
                Ok(()) => {
                    awaiting_field = true;
                    last_advance = Instant::now();
                }
                Err(e) => film.on_failure(&e, now),
            }
        }
        let (w, h) = ctx.session.terminal_size();
        let mono = ctx.session.color_depth() == ColorDepth::Mono;
        ctx.set_root(film.view(now, w, h, mono));
    }
    Ok(())
}

/// Commit the film's record atomically: `film.capture` (frames) and `film.trace` (causal trace).
fn record_film(dir: &std::path::Path, rec: &film::FilmRecord) -> io::Result<(u64, u64)> {
    std::fs::create_dir_all(dir)?;
    capture::write_capture_file(
        &dir.join("film.capture"),
        &rec.frames,
        &capture::CaptureLimits::default(),
    )?;
    capture::atomic_write(&dir.join("film.trace"), |w| {
        trace::write_trace(w, &rec.trace).map_err(io::Error::from)
    })?;
    Ok((
        capture::content_digest(&rec.frames),
        rec.trace.causal_digest(),
    ))
}

/// Replay a recorded film with NO producer: re-derive its decisions from the record alone.
fn replay_film_cmd(dir: &str) -> ExitCode {
    let d = std::path::Path::new(dir);
    let read = || -> Result<(Vec<capture::CapturedFrame>, trace::CausalTrace), String> {
        let cap = std::fs::read(d.join("film.capture")).map_err(|e| e.to_string())?;
        let tr = std::fs::read(d.join("film.trace")).map_err(|e| e.to_string())?;
        let frames = capture::read_capture(&mut cap.as_slice()).map_err(|e| e.to_string())?;
        let t = trace::read_trace(&mut tr.as_slice()).map_err(|e| e.to_string())?;
        Ok((frames, t))
    };
    let (frames, t) = match read() {
        Ok(v) => v,
        Err(e) => {
            println!("film-replay FAILED: {e}");
            return ExitCode::FAILURE;
        }
    };
    match film::replay_film(&frames, &t) {
        Ok(r) => {
            println!("film-path: {}", film::beat_path(&r.beats));
            println!("film-beats-digest: {:016x}", film::beats_digest(&r.beats));
            println!(
                "film-replay: transforms {} · outcome {:?} · capture-digest {:016x} causal-digest {:016x}",
                r.transforms,
                r.last_outcome,
                capture::content_digest(&frames),
                t.causal_digest(),
            );
            ExitCode::SUCCESS
        }
        Err(e) => {
            println!("film-replay FAILED: {e:?}");
            ExitCode::FAILURE
        }
    }
}

// ---------------------------------------------------------------------------
// Selfcheck — the live proof that the film is instrument-driven.
// ---------------------------------------------------------------------------

fn selfcheck() -> ExitCode {
    let model = Model::new(SourceId(42), 1);
    let mut ok = true;
    let mut check = |name: &str, pass: bool| {
        println!("[{}] {name}", if pass { "PASS" } else { "FAIL" });
        ok &= pass;
    };

    // 1 — determinism / replay: the same (tick, selection) renders identically.
    {
        let sel = model.hotspot_center(3);
        let a = cinema::stage_tick(&model, 3, sel, ANCHOR);
        let b = cinema::stage_tick(&model, 3, sel, ANCHOR);
        check(
            "determinism: identical (tick, selection) ⇒ identical shot and pixels",
            a.shot == b.shot && a.frame.surface == b.frame.surface,
        );
    }

    // 2 — field dependency: move the model (a later tick) ⇒ the shot tracks the
    // peak and the pixels change. The film is generated by the model.
    {
        let sel = model.hotspot_center(0); // hold the selection fixed
        let a = cinema::stage_tick(&model, 1, sel, ANCHOR);
        let b = cinema::stage_tick(&model, 6, sel, ANCHOR);
        check(
            "field dependency: a later model tick moves the focus and the pixels",
            a.shot.focus != b.shot.focus && a.frame.surface != b.frame.surface,
        );
    }

    // 3 — selection dependency: a probe on the peak punches in; a cold probe
    // holds wide. The selection drives the shot.
    {
        let (data, mask) = model.frame_buffers(4);
        let view = FieldView::new(model.extent(), &data, Some(&mask)).unwrap();
        let obs = observe(&view, model.source(), model.epoch(), 4);
        let on = obs.peak_center.unwrap();
        let cold = Point::new(1.0, 1.0);
        let shot_on = compose(&obs, &view.probe(on), model.extent());
        let shot_cold = compose(&obs, &view.probe(cold), model.extent());
        let f_on = render_shot(&view, &shot_on, ANCHOR);
        let f_cold = render_shot(&view, &shot_cold, ANCHOR);
        check(
            "selection dependency: probe on the peak punches in, a cold probe holds wide",
            shot_on.emphasis == Emphasis::PunchIn
                && shot_cold.emphasis == Emphasis::Wide
                && f_on.surface != f_cold.surface,
        );
    }

    // 4 — decoy invariance (negative control): perturbing a masked cell's hidden
    // value changes nothing the shot reads, so the shot and framed pixels are
    // identical. The dependency is specific, not "everything perturbs everything".
    {
        let (mut data, mask) = model.frame_buffers(4);
        let sel = Point::new(1.0, 1.0);
        let v0 = FieldView::new(model.extent(), &data, Some(&mask)).unwrap();
        let o0 = observe(&v0, model.source(), model.epoch(), 4);
        let s0 = compose(&o0, &v0.probe(sel), model.extent());
        let f0 = render_shot(&v0, &s0, ANCHOR);
        // The dropout patch is cols 2..8 × rows 16..22; (2,16) is masked.
        let decoy = 16 * cinema::COLS + 2;
        data[decoy] = 1.0e9;
        let v1 = FieldView::new(model.extent(), &data, Some(&mask)).unwrap();
        let o1 = observe(&v1, model.source(), model.epoch(), 4);
        let s1 = compose(&o1, &v1.probe(sel), model.extent());
        let f1 = render_shot(&v1, &s1, ANCHOR);
        check(
            "decoy invariance: a masked cell's hidden value never reaches the shot",
            o0 == o1 && s0 == s1 && f0.surface == f1.surface,
        );
    }

    println!(
        "\n{}",
        if ok {
            "selfcheck OK"
        } else {
            "selfcheck FAILED"
        }
    );
    if ok {
        ExitCode::SUCCESS
    } else {
        ExitCode::FAILURE
    }
}
